#include <bits/stdc++.h>
using namespace std;struct A{int w,d,z;};A T[1200][2];bool present[1200];vector<int>states;struct C{int idx,pos,halt,h,steps;bitset<512>initial,want;vector<int>visits;};vector<C>cases;int off=128;
bitset<512>parse(string s){bitset<512>t;if(s=="x")return t;istringstream ss(s);string z;while(getline(ss,z,',')){int h=stoi(z)+off;if(h<0||h>=512)throw runtime_error("bounds");t[h]=1;}return t;}
bool clean(int h,const bitset<512>&t){if(h<1||h+64>=512||!t[h-1])return false;for(int i=0;i<h-1;i++)if(t[i])return false;int header=h+52;while(header<512&&!t[header])header++;if(header>=512||header<h+64)return false;int last=511;while(last>=0&&!t[last])last--;int p=header+1,n=0;while(p<last){if(t[p]||!t[p+1])return false;p++;while(p<512&&t[p])p++;n++;}return p==last+1&&n>=10;}
int run(C&c,int eq,int eb,int nz,bool trace=false){int q=84,root=q,h=off;auto tape=c.initial;bitset<2400>seen;int limit=trace?100000:max(10000,c.steps*6+300);for(int step=0;step<=limit;step++){if(step&&((q==root&&clean(h,tape))||q==254)){if(c.halt){if(q==254)return step;}else if(q==root&&h==off+c.h&&tape==c.want)return step;return-1;}if(step==limit||h<0||h>=512||!present[q])return-2;int x=tape[h];if(trace&&!seen[q*2+x]){seen[q*2+x]=1;c.visits.push_back(q*2+x);}A t=T[q][x];if(q==eq&&x==eb)t.z=nz;tape[h]=t.w;h+=t.d;q=t.z;}return-2;}
int main(int argc,char**argv){ifstream in(argv[1]);string line;while(getline(in,line)){if(line.empty()||line[0]=='#')continue;istringstream s(line);int q,b,w,z;char d;s>>q>>b>>w>>d>>z;T[q][b]={w,d=='R'?1:-1,z};present[q]=true;}for(int q=0;q<1200;q++)if(present[q])states.push_back(q);ifstream ci(argv[2]);while(getline(ci,line)){istringstream s(line);C c;string x,y;s>>c.idx>>c.pos>>c.halt>>c.h>>x>>y;c.initial=parse(x);c.want=parse(y);c.steps=100000;cases.push_back(c);}vector<int>by[2400];long long baseSteps=0;for(int i=0;i<(int)cases.size();i++){auto&c=cases[i];c.steps=run(c,-1,-1,-1,true);if(c.steps<0){cerr<<"BAD BASE "<<i<<' '<<c.steps<<'\n';return 2;}baseSteps+=c.steps;for(int q:c.visits)by[q].push_back(i);}cerr<<"BASE "<<cases.size()<<" cases "<<baseSteps<<" steps\n";
map<int,vector<A>>opts;ifstream oi(argv[3]);while(getline(oi,line)){istringstream z(line);vector<int>v;int x;while(z>>x)v.push_back(x);if(v.size()==5){int eq=v[0],eb=v[1];A t=T[eq][eb];t.z=v[3];opts[eq*2+eb].push_back(t);}else if(v.size()==7)opts[v[0]*2+v[1]].push_back({v[3],v[4],v[5]});}long long tries=0,passed=0;for(int a:states){if(a==0||a==84)continue;vector<int>es,affected;bool possible=true;for(int q:states)for(int bit=0;bit<2;bit++)if(q!=a&&T[q][bit].z==a){int e=2*q+bit;es.push_back(e);if(opts[e].empty())possible=false;affected.insert(affected.end(),by[e].begin(),by[e].end());}if(!possible||es.empty())continue;sort(affected.begin(),affected.end());affected.erase(unique(affected.begin(),affected.end()),affected.end());cerr<<"TRY ELIMINATE "<<a<<" EDGES "<<es.size()<<" CASES "<<affected.size()<<'\n';vector<A>saved;for(int e:es)saved.push_back(T[e/2][e%2]);present[a]=false;function<void(int)>visit=[&](int depth){if(depth<(int)es.size()){int e=es[depth];for(A t:opts[e]){if(t.z==a)continue;T[e/2][e%2]=t;visit(depth+1);}return;}tries++;for(int i:affected)if(run(cases[i],-1,-1,-1)<0)return;passed++;cout<<a;for(int e:es){A t=T[e/2][e%2];cout<<" | "<<e/2<<' '<<e%2<<' '<<t.w<<' '<<t.d<<' '<<t.z;}cout<<'\n'<<flush;};visit(0);present[a]=true;for(int i=0;i<(int)es.size();i++)T[es[i]/2][es[i]%2]=saved[i];}cerr<<"COMBINATIONS "<<tries<<" PASSED "<<passed<<'\n';}
